mapper.select:
select project_id, user_id, title, research_question, target_venue, writing_status,
       progress_note, create_time, update_time
from academic_project
where user_id = #{userId}
order by update_time desc, id desc
limit #{limit}

select project_id, user_id, title, research_question, target_venue, writing_status,
       progress_note, create_time, update_time
from academic_project
where user_id = #{userId}
  and project_id = #{projectId}
limit 1

select project_id, user_id, file_id, file_name, file_type, folder_type,
       summary, content_preview, create_time
from academic_project_file
where user_id = #{userId}
  and project_id = #{projectId}
order by create_time asc, id asc

mapper.insert:
insert into academic_project_patch (
  project_id, user_id, patch_id, file_id, title, reason,
  before_text, after_text, status, create_time, apply_time
) values (
  #{projectId}, #{userId}, #{patchId}, #{fileId}, #{title}, #{reason},
  #{beforeText}, #{afterText}, #{status}, #{createTime}, #{applyTime}
)
on duplicate key update patch_id = values(patch_id)

mapper.update:
update academic_project_patch
set status = #{status},
    apply_time = #{applyTime}
where user_id = #{userId}
  and project_id = #{projectId}
  and patch_id = #{patchId}

mapper.select:
select project_id, user_id, patch_id, file_id, title, reason,
       before_text, after_text, status, create_time, apply_time
from academic_project_patch
where user_id = #{userId}
  and project_id = #{projectId}
order by create_time desc, id desc

mapper.update:
update academic_project_file
set summary = #{summary},
    content_preview = #{contentPreview}
where user_id = #{userId}
  and project_id = #{projectId}
  and file_id = #{fileId}

update academic_project
set update_time = #{updateTime}
where user_id = #{userId}
  and project_id = #{projectId}
